object Tangled {
  def tangled(a: Int): Int = {
    var x = a
    if (a > 0) { x = x + 0 }
    if (a > 1) { x = x + 1 }
    if (a > 2) { x = x + 2 }
    if (a > 3) { x = x + 3 }
    if (a > 4) { x = x + 4 }
    if (a > 5) { x = x + 5 }
    if (a > 6) { x = x + 6 }
    if (a > 7) { x = x + 7 }
    if (a > 8) { x = x + 8 }
    if (a > 9) { x = x + 9 }
    if (a > 10) { x = x + 10 }
    if (a > 11) { x = x + 11 }
    if (a > 12) { x = x + 12 }
    if (a > 13) { x = x + 13 }
    if (a > 14) { x = x + 14 }
    if (a > 15) { x = x + 15 }
    x
  }
}
